/** One generated file: its path relative to the repository root and its content. */
export interface GeneratedFile {
  readonly path: string
  readonly content: string
}

/** Text as JSON with a two-space indent and a final newline. */
export const jsonText = (value: unknown): string => `${JSON.stringify(value, null, 2)}\n`

/**
 * The note a generated file carries, where its format allows one: the build script that wrote it,
 * as a path from the repository root, and the source it came from.
 */
export const generatedNote = (builder: string, source: string): string =>
  `Generated by ${builder} from ${source}; edit the source and rebuild.`

/**
 * Bun's comment above each bundled module, which names the module's path, so a generator drops it
 * to make the bundle the same on every machine. A path with spaces matches as long as it holds a
 * separator, which tells it from a prose comment that happens to end in a file extension.
 */
export const MODULE_COMMENT = /^\/\/ (?:\S+|.*[\\/].*)\.(?:[cm]?[jt]s|json|md)$\n/gm
